/* Self test against tests/test_vectors.json (generated by the Python reference's tests/make_vectors.py): every
 * header packs and unpacks byte-exactly, every payload transform reproduces the wire bytes, and the JSON shapes of
 * the log channel parse and re-serialise as Python writes them. */
#include "internal.h"

#include <stdio.h>

typedef struct {
    FILE *out;
    int failures;
} report;

#define CHECK(r, cond, ...) do { if (!(cond)) { (r)->failures++; if ((r)->out) { fprintf((r)->out, "FAIL: "); fprintf((r)->out, __VA_ARGS__); fputc('\n', (r)->out); } } } while (0)

static uint8_t *hex_to_bytes(const char *hex, size_t *len) {
    size_t n = strlen(hex);
    if (n % 2) return NULL;
    uint8_t *out = malloc(n / 2 + 1);
    if (out == NULL) return NULL;
    if (ppc_hex_decode(hex, n, out, n / 2) != PPC_OK) { free(out); return NULL; }
    *len = n / 2;
    return out;
}

static char *read_file(const char *path, size_t *len) {
    FILE *f = fopen(path, "rb");
    if (f == NULL) return NULL;
    ppc_buf b = {0};
    char chunk[8192];
    size_t n;
    while ((n = fread(chunk, 1, sizeof chunk, f)) > 0) if (ppc_buf_append(&b, chunk, n) != PPC_OK) { fclose(f); ppc_buf_free(&b); return NULL; }
    fclose(f);
    if (ppc_buf_append(&b, "", 1) != PPC_OK) { ppc_buf_free(&b); return NULL; }
    *len = b.len - 1;
    return (char *)b.data;
}

static void check_frame(report *r, const char *name, const ppc_json *v, const ppc_json *ids, const uint8_t *key,
                        const uint8_t *nonce) {
    size_t header_len = 0, frame_len = 0;
    uint8_t *header = hex_to_bytes(ppc_json_get_string(v, "header_hex", ""), &header_len);
    uint8_t *frame = hex_to_bytes(ppc_json_get_string(v, "frame_hex", ""), &frame_len);
    const char *plain = ppc_json_get_string(v, "payload_utf8", "");
    size_t plain_len = strlen(plain);
    if (header == NULL || frame == NULL || frame_len < header_len) {
        CHECK(r, false, "%s: unusable vector", name);
        free(header); free(frame);
        return;
    }
    /* Build the header from the fields and pack it. */
    ppc_header h;
    memset(&h, 0, sizeof h);
    h.version = (uint16_t)ppc_json_get_number(v, "header_version", 0);
    h.data_length = frame_len - header_len;
    snprintf(h.method_name, sizeof h.method_name, "%s", ppc_json_get_string(v, "method_name", ""));
    h.request_id = (uint32_t)ppc_json_get_number(v, "request_id", 0);
    ppc_uuid_parse(ppc_json_get_string(ids, "sender_id", ""), &h.sender_id);
    ppc_uuid_parse(ppc_json_get_string(ids, "sender_token", ""), &h.sender_token);
    bool response_expected = ppc_json_get_bool(v, "response_expected", false);
    bool compressed = ppc_json_get_bool(v, "compressed", false);
    bool encrypted = ppc_json_get_bool(v, "encrypted", false);
    bool keep_alive = ppc_json_get_bool(v, "keep_alive", false);
    bool aes_gcm = ppc_json_get_bool(v, "aes_gcm", false);
    h.bitflags = (uint16_t)((response_expected ? PPC_FLAG(PPC_BIT_RESPONSE_EXPECTED) : 0) | (compressed ? PPC_FLAG(PPC_BIT_COMPRESSED) : 0)
                            | (encrypted ? PPC_FLAG(PPC_BIT_ENCRYPTED) : 0) | (keep_alive ? PPC_FLAG(PPC_BIT_KEEP_ALIVE) : 0)
                            | (aes_gcm ? PPC_FLAG(PPC_BIT_AES_GCM) : 0));
    const char *remote = ppc_json_get_string(v, "remote_id", NULL);
    if (remote) ppc_uuid_parse(remote, &h.remote_id);
    uint8_t packed[PPC_FRAME_HEADER_MAX];
    size_t packed_len = 0;
    int rc = ppc_header_pack(&h, packed, &packed_len);
    CHECK(r, rc == PPC_OK, "%s: pack failed (%s)", name, ppc_strerror(rc));
    CHECK(r, packed_len == header_len && memcmp(packed, header, header_len) == 0, "%s: packed header differs from header_hex", name);
    CHECK(r, header_len == ppc_header_length(h.version), "%s: header length %zu, expected %zu", name, header_len, ppc_header_length(h.version));
    CHECK(r, memcmp(frame, header, header_len) == 0, "%s: frame does not start with its header", name);
    /* Unpack and compare every field. */
    ppc_header u;
    rc = ppc_header_unpack(header, header_len, &u);
    CHECK(r, rc == PPC_OK, "%s: unpack failed (%s)", name, ppc_strerror(rc));
    if (rc == PPC_OK) {
        CHECK(r, u.version == h.version, "%s: version %u", name, u.version);
        CHECK(r, u.data_length == h.data_length, "%s: data_length %llu, expected %llu", name, (unsigned long long)u.data_length, (unsigned long long)h.data_length);
        CHECK(r, strcmp(u.method_name, h.method_name) == 0, "%s: method %s", name, u.method_name);
        CHECK(r, u.request_id == h.request_id, "%s: request_id %u", name, u.request_id);
        CHECK(r, ppc_uuid_equal(&u.sender_id, &h.sender_id), "%s: sender_id", name);
        CHECK(r, ppc_uuid_equal(&u.sender_token, &h.sender_token), "%s: sender_token", name);
        CHECK(r, u.bitflags == h.bitflags, "%s: bitflags %u, expected %u", name, u.bitflags, h.bitflags);
        CHECK(r, ppc_uuid_equal(&u.remote_id, &h.remote_id), "%s: remote_id", name);
        CHECK(r, ppc_header_flag(&u, PPC_BIT_RESPONSE_EXPECTED) == response_expected, "%s: response_expected flag", name);
        CHECK(r, ppc_header_flag(&u, PPC_BIT_COMPRESSED) == compressed, "%s: compressed flag", name);
        CHECK(r, ppc_header_flag(&u, PPC_BIT_ENCRYPTED) == encrypted, "%s: encrypted flag", name);
        CHECK(r, ppc_header_flag(&u, PPC_BIT_KEEP_ALIVE) == keep_alive, "%s: keep_alive flag", name);
        CHECK(r, ppc_header_flag(&u, PPC_BIT_AES_GCM) == aes_gcm, "%s: aes_gcm flag", name);
    }
    /* Payload transforms. */
    const uint8_t *wire = frame + header_len;
    size_t wire_len = frame_len - header_len;
    uint8_t *inner = NULL;      /* the (possibly compressed) payload before encryption */
    size_t inner_len = 0;
    if (encrypted) {
        CHECK(r, wire_len >= PPC_NONCE_BYTES + PPC_TAG_BYTES, "%s: encrypted payload too short", name);
        if (wire_len >= PPC_NONCE_BYTES + PPC_TAG_BYTES) {
            CHECK(r, memcmp(wire, nonce, PPC_NONCE_BYTES) == 0, "%s: nonce differs from the fixed test nonce", name);
            inner_len = wire_len - PPC_NONCE_BYTES - PPC_TAG_BYTES;
            inner = malloc(inner_len + 1);
            rc = ppc_aead_open(aes_gcm, key, wire, header, header_len, wire + PPC_NONCE_BYTES, wire_len - PPC_NONCE_BYTES, inner);
            CHECK(r, rc == PPC_OK, "%s: decryption failed (%s)", name, ppc_strerror(rc));
            if (rc == PPC_OK) {
                uint8_t *sealed = malloc(inner_len + PPC_TAG_BYTES);
                rc = ppc_aead_seal(aes_gcm, key, nonce, header, header_len, inner, inner_len, sealed);
                CHECK(r, rc == PPC_OK && memcmp(sealed, wire + PPC_NONCE_BYTES, inner_len + PPC_TAG_BYTES) == 0,
                      "%s: re-encryption with the fixed nonce differs from the wire bytes", name);
                free(sealed);
                /* A flipped header byte (the associated data) must fail authentication. */
                uint8_t tampered[PPC_FRAME_HEADER_MAX];
                memcpy(tampered, header, header_len);
                tampered[2 + 8 + 2] ^= 0x01;       /* a method-name byte */
                uint8_t *scratch = malloc(inner_len + 1);
                rc = ppc_aead_open(aes_gcm, key, wire, tampered, header_len, wire + PPC_NONCE_BYTES, wire_len - PPC_NONCE_BYTES, scratch);
                CHECK(r, rc == PPC_ERR_AUTH, "%s: tampered header was not detected", name);
                free(scratch);
            } else {
                free(inner);
                inner = NULL;
            }
        }
    } else {
        inner = malloc(wire_len + 1);
        memcpy(inner, wire, wire_len);
        inner_len = wire_len;
    }
    if (inner) {
        if (compressed) {
            uint8_t *inflated = NULL;
            size_t inflated_len = 0;
            rc = ppc_zlib_decompress(inner, inner_len, &inflated, &inflated_len, 0);
            CHECK(r, rc == PPC_OK, "%s: decompression failed (%s)", name, ppc_strerror(rc));
            CHECK(r, rc == PPC_OK && inflated_len == plain_len && memcmp(inflated, plain, plain_len) == 0,
                  "%s: decompressed payload differs from payload_utf8", name);
            free(inflated);
            /* Our own compression must round-trip (zlib builds differ in output bytes, so only the round trip is checked). */
            uint8_t *deflated = NULL;
            size_t deflated_len = 0;
            rc = ppc_zlib_compress((const uint8_t *)plain, plain_len, &deflated, &deflated_len);
            CHECK(r, rc == PPC_OK && deflated_len < plain_len, "%s: compression did not shrink the payload", name);
            if (rc == PPC_OK) {
                rc = ppc_zlib_decompress(deflated, deflated_len, &inflated, &inflated_len, 0);
                CHECK(r, rc == PPC_OK && inflated_len == plain_len && memcmp(inflated, plain, plain_len) == 0, "%s: compression round trip", name);
                free(inflated);
            }
            free(deflated);
        } else {
            CHECK(r, inner_len == plain_len && memcmp(inner, plain, plain_len) == 0, "%s: payload differs from payload_utf8", name);
        }
    }
    free(inner);
    free(header);
    free(frame);
}

static void check_round_trip(report *r, const char *name, const char *text) {
    char err[128];
    ppc_json *v = ppc_json_parse(text, strlen(text), err, sizeof err);
    CHECK(r, v != NULL, "%s: does not parse: %s", name, err);
    if (v == NULL) return;
    char *dumped = ppc_json_dump(v);
    CHECK(r, dumped && strcmp(dumped, text) == 0, "%s: re-serialised form differs:\n  %s\n  %s", name, text, dumped ? dumped : "(null)");
    free(dumped);
    ppc_json_free(v);
}

int ppc_selftest_vectors(const char *path, FILE *out) {
    size_t len = 0;
    char *text = read_file(path, &len);
    if (text == NULL) { if (out) fprintf(out, "cannot read %s\n", path); return -1; }
    char err[128];
    ppc_json *root = ppc_json_parse(text, len, err, sizeof err);
    free(text);
    if (root == NULL) { if (out) fprintf(out, "%s: not JSON: %s\n", path, err); return -1; }
    report r = {out, 0};
    const ppc_json *constants = ppc_json_get(root, "constants");
    CHECK(&r, (int)ppc_json_get_number(constants, "header_length_v1", 0) == PPC_HEADER_V1_LENGTH, "header_length_v1");
    CHECK(&r, (int)ppc_json_get_number(constants, "header_length_v2", 0) == PPC_HEADER_V2_LENGTH, "header_length_v2");
    CHECK(&r, (int)ppc_json_get_number(constants, "bit_response_expected", -1) == PPC_BIT_RESPONSE_EXPECTED, "bit_response_expected");
    CHECK(&r, (int)ppc_json_get_number(constants, "bit_compressed", -1) == PPC_BIT_COMPRESSED, "bit_compressed");
    CHECK(&r, (int)ppc_json_get_number(constants, "bit_encrypted", -1) == PPC_BIT_ENCRYPTED, "bit_encrypted");
    CHECK(&r, (int)ppc_json_get_number(constants, "bit_keep_alive", -1) == PPC_BIT_KEEP_ALIVE, "bit_keep_alive");
    CHECK(&r, (int)ppc_json_get_number(constants, "bit_aes_gcm", -1) == PPC_BIT_AES_GCM, "bit_aes_gcm");
    CHECK(&r, ppc_json_get_number(constants, "request_id_max_v1", 0) == (double)PPC_REQUEST_ID_MAX_V1, "request_id_max_v1");
    CHECK(&r, ppc_json_get_number(constants, "request_id_max_v2", 0) == (double)PPC_REQUEST_ID_MAX_V2, "request_id_max_v2");
    CHECK(&r, (int)ppc_json_get_number(constants, "nonce_bytes", 0) == PPC_NONCE_BYTES, "nonce_bytes");
    CHECK(&r, (int)ppc_json_get_number(constants, "tag_bytes", 0) == PPC_TAG_BYTES, "tag_bytes");
    CHECK(&r, (int)ppc_json_get_number(constants, "key_bytes", 0) == PPC_KEY_BYTES, "key_bytes");
    const ppc_json *levels = ppc_json_get(constants, "syslog_prefix_levels");
    for (size_t i = 0; levels && i < levels->count; i++)
        CHECK(&r, levels->items[i]->type == PPC_JSON_STRING && ppc_log_level_from_name(levels->items[i]->string) > 0,
              "syslog level %s unknown", levels->keys[i]);

    const ppc_json *ids = ppc_json_get(root, "identities");
    uint8_t key[PPC_KEY_BYTES], nonce[PPC_NONCE_BYTES];
    const char *key_hex = ppc_json_get_string(ids, "key_hex", ""), *nonce_hex = ppc_json_get_string(ids, "nonce_hex", "");
    CHECK(&r, ppc_hex_decode(key_hex, strlen(key_hex), key, sizeof key) == PPC_OK, "key_hex");
    CHECK(&r, ppc_hex_decode(nonce_hex, strlen(nonce_hex), nonce, sizeof nonce) == PPC_OK, "nonce_hex");
    ppc_uuid sender;
    char hex[33];
    ppc_uuid_parse(ppc_json_get_string(ids, "sender_id", ""), &sender);
    ppc_uuid_hex(&sender, hex);
    CHECK(&r, strcmp(hex, "11111111222233334444555555555555") == 0, "uuid hex %s", hex);

    const ppc_json *frames = ppc_json_get(root, "frames");
    CHECK(&r, frames && frames->type == PPC_JSON_OBJECT && frames->count > 0, "no frames");
    for (size_t i = 0; frames && i < frames->count; i++) check_frame(&r, frames->keys[i], frames->items[i], ids, key, nonce);

    const ppc_json *log = ppc_json_get(root, "log_channel");
    const char *line = ppc_json_get_string(log, "json_line", "");
    ppc_json *record = ppc_json_parse(line, strlen(line), err, sizeof err);
    CHECK(&r, record != NULL, "json_line does not parse: %s", err);
    if (record) {
        static const char *const required[] = {"name", "levelno", "levelname", "pathname", "lineno", "funcName", "created", "msecs", "process", "msg"};
        for (size_t i = 0; i < sizeof required / sizeof *required; i++)
            CHECK(&r, ppc_json_get(record, required[i]) != NULL, "json_line lacks %s", required[i]);
        CHECK(&r, strcmp(ppc_json_get_string(record, "msg", ""), "device d1 offline") == 0, "json_line msg");
        CHECK(&r, (int)ppc_json_get_number(record, "levelno", 0) == PPC_LOG_WARNING
              && ppc_log_level_from_name(ppc_json_get_string(record, "levelname", "")) == PPC_LOG_WARNING, "json_line level");
        char *dumped = ppc_json_dump(record);
        CHECK(&r, dumped && strcmp(dumped, line) == 0, "json_line re-serialised form differs");
        free(dumped);
        ppc_json_free(record);
    }
    /* Our own records carry the same required attributes. */
    char *own = ppc_log_record_json(PPC_LOG_INFO, "test", "/x/y.c", 7, "f", "hello");
    ppc_json *own_record = own ? ppc_json_parse(own, strlen(own), err, sizeof err) : NULL;
    CHECK(&r, own_record != NULL, "own log record does not parse");
    if (own_record) {
        static const char *const required[] = {"name", "levelno", "levelname", "pathname", "lineno", "funcName", "created", "msecs", "process", "msg"};
        for (size_t i = 0; i < sizeof required / sizeof *required; i++)
            CHECK(&r, ppc_json_get(own_record, required[i]) != NULL, "own log record lacks %s", required[i]);
        ppc_json_free(own_record);
    }
    free(own);
    check_round_trip(&r, "register_peer_reply", ppc_json_get_string(log, "register_peer_reply", ""));
    check_round_trip(&r, "ping_reply_example", ppc_json_get_string(log, "ping_reply_example", ""));
    check_round_trip(&r, "set_log_level_request", ppc_json_get_string(log, "set_log_level_request", ""));
    check_round_trip(&r, "log_batch_payload", ppc_json_get_string(log, "log_batch_payload", ""));
    const char *request = ppc_json_get_string(log, "set_log_level_request", "");
    ppc_json *req = ppc_json_parse(request, strlen(request), err, sizeof err);
    int level = req ? ppc_log_level_from_name(ppc_json_get_string(req, "level", "")) : -1;
    ppc_json_free(req);
    ppc_json *reply = ppc_json_new_object();
    ppc_json_object_set(reply, "level", ppc_json_new_string(ppc_log_level_name(level)));
    char *reply_text = ppc_json_dump(reply);
    ppc_json_free(reply);
    CHECK(&r, reply_text && strcmp(reply_text, ppc_json_get_string(log, "set_log_level_reply", "")) == 0, "set_log_level reply %s", reply_text ? reply_text : "");
    free(reply_text);
    const char *batch = ppc_json_get_string(log, "log_batch_payload", "");
    ppc_json *batch_v = ppc_json_parse(batch, strlen(batch), err, sizeof err);
    CHECK(&r, batch_v && (int)ppc_json_get_number(batch_v, "dropped", -1) == 2, "log_batch_payload dropped");
    ppc_json_free(batch_v);
    ppc_json_free(root);
    if (out) fprintf(out, "%s: %d failure(s)\n", path, r.failures);
    return r.failures;
}
